
.battle-panel {
  width: 100%;
  max-width: 900px;
  margin: 16px auto;
  padding: 14px;
  border-radius: 10px;
  background: var(--b-bg);
  border: 1px solid var(--b-border);
  color: var(--b-text);
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-size: 13px;
  position: relative;
}

.battle-panel.shaking {
  animation: panel-shake 0.28s ease;
}

@keyframes panel-shake {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-3px, 2px); }
  40% { transform: translate(3px, -2px); }
  60% { transform: translate(-2px, -1px); }
  80% { transform: translate(2px, 1px); }
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--b-border);
}

.battle-hint {
  font-size: 12px;
  line-height: 1.5;
  padding: 5px 10px;
  border-radius: 6px;
  border: 1px dashed var(--b-accent-2);
  background: var(--b-surface);
  color: var(--b-accent-2);
}

.title {
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--b-accent-2);
}

.round {
  padding: 1px 8px;
  border: 1px solid var(--b-border);
  border-radius: 10px;
  font-size: 12px;
  color: var(--b-muted);
}

.current {
  font-size: 12px;
}

.current.muted {
  color: var(--b-muted);
}

.head-btn {
  padding: 5px 12px;
  border: 1px solid var(--b-accent);
  border-radius: 5px;
  background: transparent;
  color: var(--b-accent);
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s, color 0.15s;
}

.head-btn:first-of-type {
  margin-left: auto;
}

.head-btn:hover {
  background: rgba(200, 69, 47, 0.15);
}

.head-btn.off {
  border-color: var(--b-border);
  color: var(--b-muted);
}

.speed-order {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.speed-chip {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid var(--b-border);
  background: var(--b-surface);
  color: var(--b-muted);
}

.speed-chip.active {
  border-color: var(--b-accent-2);
  color: var(--b-accent-2);
}

.speed-chip.dead {
  opacity: 0.35;
  text-decoration: line-through;
}

.columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.side {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.side h3 {
  margin: 0;
  font-size: 12px;
  color: var(--b-muted);
  font-weight: 500;
}

.target-area,
.player-area {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hit-summary {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 12px;
  padding: 6px 10px;
  border-radius: 6px;
  background: var(--b-surface);
  border: 1px solid var(--b-border);
}

.hit-summary.crit {
  border-color: var(--b-accent-2);
  box-shadow: 0 0 12px rgba(217, 164, 65, 0.25);
}

.hit-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  width: 100%;
}

.hit-text {
  flex: 1 1 200px;
}

.sp-pop {
  font-size: 11px;
  font-weight: 700;
  padding: 0 5px;
  border-radius: 6px;
  border: 1px solid var(--b-border);
}

.sp-pop.up {
  color: #8fe0a2;
  border-color: #4fbf6a;
}

.sp-pop.down {
  color: #e88a7c;
  border-color: #d94b3a;
}

.hit-badge {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  padding: 1px 6px;
  border-radius: 8px;
  animation: badge-in 0.35s ease;
}

.hit-badge.chaos {
  color: #1b1207;
  background: var(--b-chaos);
}

.hit-badge.defend {
  color: #06121b;
  background: #7fc6e0;
}

.hit-badge.death {
  color: #fff;
  background: var(--b-enemy);
  box-shadow: 0 0 10px rgba(200, 69, 47, 0.7);
}

.hit-badge.corrosion {
  color: #12061b;
  background: linear-gradient(90deg, #a05de0, #e05297);
  box-shadow: 0 0 10px rgba(160, 93, 224, 0.7);
}

@keyframes badge-in {
  0% { transform: scale(0.5) rotate(-8deg); opacity: 0; }
  70% { transform: scale(1.15); }
  100% { transform: scale(1); opacity: 1; }
}

.dmg-pop {
  font-weight: 800;
  color: var(--b-hp);
  animation: dmg-rise 0.6s ease;
}

.dmg-pop.crit {
  color: var(--b-accent-2);
  font-size: 15px;
  text-shadow: 0 0 10px rgba(217, 164, 65, 0.8);
}

@keyframes dmg-rise {
  0% {
    transform: translateY(8px) scale(0.7);
    opacity: 0;
  }
  100% {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

@media (max-width: 640px) {
  .columns {
    grid-template-columns: 1fr;
  }
}
